import random, math
from decimal import Decimal, ROUND_HALF_EVEN, localcontext
from lidar_scan import tiles
f=tiles.assess_tile_pyramid_deltas

def q(v):
    r=float(Decimal(v).quantize(Decimal("0.000001"), rounding=ROUND_HALF_EVEN))
    return 0.0 if r==0.0 else r

def ref(e,r):
    out=[]
    for el,rl in zip(e,r):
        lvl=[]
        rmap={(t[0],t[1]):t for t in rl}
        for a in el:
            b=rmap[(a[0],a[1])]
            with localcontext() as c:
                c.prec=50; c.rounding=ROUND_HALF_EVEN
                dz=q(Decimal(str(a[6]))-Decimal(str(b[6])))
                dx=q(Decimal(str(a[7]))-Decimal(str(b[7])))
            lvl.append((a[0],a[1],a[2],a[3],a[4],a[5],dz,dx,a[8]-b[8]))
        out.append(tuple(lvl))
    return tuple(out)

def mk_tile(tx,ty,w,zl,zh,c):
    return (tx,ty,tx*w,ty*w,tx*w+w-1,ty*w+w-1,
            round(uniform(zl,zh),6), round(uniform(zl,zh),6) and 0, c)
random.seed(42)
def uniform(a,b): return random.uniform(a,b)

for trial in range(3000):
    levels=random.randint(1,4); w=4
    coords=[sorted(set((random.randint(-3,3),random.randint(-3,3))
                       for _ in range(random.randint(0,8))))
            for _ in range(levels)]
    def build():
        pyr=[]
        for cs in coords:
            tiles_lvl=[]
            for tx,ty in cs:
                zlo=round(random.uniform(-50,50),6)
                zhi=zlo+abs(round(random.uniform(0,20),6))
                tiles_lvl.append((tx,ty,tx*w,ty*w,tx*w+w-1,ty*w+w-1,zlo,zhi,random.randint(0,1000)))
            pyr.append(tuple(tiles_lvl))
        return tuple(pyr)
    e=build(); r=build()
    got=f(e,r); want=ref(e,r)
    if got!=want:
        print("MISMATCH",trial); print(e); print(r); print(got); print(want); break
else:
    print("3000 random differential trials OK")
